    deepExplanation: "Example:\n\n```ts\nimport { useMemo, useState } from \"react\";\n\ntype Item = {\n  id: string;\n  label: string;\n};\n\ntype Props = {\n  items: readonly Item[];\n};\n\nexport function ExampleFeature({ items }: Props) {\n  const [selectedId, setSelectedId] = useState<string | null>(null);\n\n  const selected = useMemo(\n    () => items.find((item) => item.id === selectedId) ?? null,\n    [items, selectedId],\n  );\n\n  return (\n    <section aria-label=\"Example feature\">\n      <ul>\n        {items.map((item) => (\n          <li key={item.id}>\n            <button\n              type=\"button\"\n              aria-pressed={selectedId === item.id}\n              onClick={() => setSelectedId(item.id)}\n            >\n              {item.label}\n            </button>\n          </li>\n        ))}\n      </ul>\n\n      <p aria-live=\"polite\">\n        {selected ? `Selected: ${selected.label}` : \"Nothing selected\"}\n      </p>\n    </section>\n  );\n}\n```\n\nProduction pattern:\n\n```ts\n// Architecture-level configuration should be environment driven.\n// Never place production secrets in client-side source.\nexport const appConfig = {\n  apiBaseUrl: import.meta.env.VITE_API_BASE_URL,\n  appVersion: import.meta.env.VITE_APP_VERSION,\n} as const;\n```",
